	const ts = (t) => new Date(t.replace(/-/g, '/')).getTime()

	export default {
		data() {
			return {
				newsList: rawNews.map(n => ({
					...n,
					timestamp: ts(n.time),
					dateLabel: n.time.slice(0, 16)   // YYYY-MM-DD HH:mm
				}))
			}
		},
		computed: {
			sortedNews() {
				// 拷贝一份再排序，避免污染原数组；时间戳越大（越新）排越前（时间倒序）
